// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Put with valid funds must succeed");
    }
}
